<?xml version="1.0" encoding="utf-8"?>
<!--
  Пример файла .map для плагина тепловых камер.
  Плагин PlgThermalCamera извлекает из этого файла все элементы Location с Type=Triangle.

  Добавленный элемент <District> определяет номер района для сортировки в таблице.

  DataItem определяются по тексту метки:
    содержит "затопл"/"flood" + "200"  - статус затопления 200мм (0=затоплено, 1=норма)
    содержит "затопл"/"flood" + "700"  - статус затопления 700мм (0=затоплено, 1=норма)
    содержит "батар"/"battery"/"заряд" - заряд батареи, %
    содержит "онлайн"/"online"/"связь" - статус связи
    содержит "200" (не затопление)     - температура трубы 200мм (напр. "Температура 200мм")
    содержит "700" (не затопление)     - температура трубы 700мм (напр. "Температура 700мм")

  Photo — относительный путь к фото в папке Views, например "Photo/1.png"
-->
<MapView>
  <InitialView>
    <Lat>55.030</Lat>
    <Lon>82.920</Lon>
    <Zoom>12</Zoom>
  </InitialView>

  <LayerGroup>
    <Options>
      <Name>Тепловые камеры</Name>
      <DefaultIcon>Site</DefaultIcon>
      <Visible>true</Visible>
      <ShowTooltips>true</ShowTooltips>
    </Options>

    <Location>
      <Lat>55.069000</Lat>
      <Lon>82.850000</Lon>
      <LatCnlNum>500107</LatCnlNum>
      <LonCnlNum>500108</LonCnlNum>
      <Name>TK-1152a</Name>
      <Descr>ул. Ленина, 15</Descr>
      <Type>Triangle</Type>
      <District>1</District>
      <Photo>Photo/tk-1152a.png</Photo>
      <StatusCnlNum>0</StatusCnlNum>
      <Data>
        <DataItem cnlNum="500101">Температура 200мм</DataItem>
        <DataItem cnlNum="500102">Температура 700мм</DataItem>
        <DataItem cnlNum="500103">Затопление 200мм</DataItem>
        <DataItem cnlNum="500104">Затопление 700мм</DataItem>
<DataItem cnlNum="500106">Онлайн</DataItem>
      </Data>
    </Location>

    <Location>
      <Lat>55.041000</Lat>
      <Lon>82.934000</Lon>
      <LatCnlNum>500207</LatCnlNum>
      <LonCnlNum>500208</LonCnlNum>
      <Name>TK-0845b</Name>
      <Descr>ул. Мира, 42</Descr>
      <Type>Triangle</Type>
      <District>1</District>
      <Photo>Photo/tk-0845b.png</Photo>
      <StatusCnlNum>0</StatusCnlNum>
      <Data>
        <DataItem cnlNum="500201">Температура 200мм</DataItem>
        <DataItem cnlNum="500202">Температура 700мм</DataItem>
        <DataItem cnlNum="500203">Затопление 200мм</DataItem>
        <DataItem cnlNum="500204">Затопление 700мм</DataItem>
        <DataItem cnlNum="500205">Батарея %</DataItem>
        <DataItem cnlNum="500206">Онлайн</DataItem>
      </Data>
    </Location>

    <Location>
      <Lat>55.012000</Lat>
      <Lon>82.880000</Lon>
      <LatCnlNum>500307</LatCnlNum>
      <LonCnlNum>500308</LonCnlNum>
      <Name>TK-2001c</Name>
      <Descr>пр. Победы, 8</Descr>
      <Type>Triangle</Type>
      <District>2</District>
      <Photo>Photo/tk-2001c.png</Photo>
      <StatusCnlNum>0</StatusCnlNum>
      <Data>
        <DataItem cnlNum="500301">Температура 200мм</DataItem>
        <DataItem cnlNum="500302">Температура 700мм</DataItem>
        <DataItem cnlNum="500303">Затопление 200мм</DataItem>
        <DataItem cnlNum="500304">Затопление 700мм</DataItem>
        <DataItem cnlNum="500305">Батарея %</DataItem>
        <DataItem cnlNum="500306">Онлайн</DataItem>
      </Data>
    </Location>

    <!-- Non-triangle locations are ignored by PlgThermalCamera -->
    <Location>
      <Lat>55.050000</Lat>
      <Lon>82.900000</Lon>
      <Name>Подстанция №5</Name>
      <Descr>Энергоподстанция</Descr>
      <Type>Circle</Type>
      <StatusCnlNum>600001</StatusCnlNum>
      <Data>
        <DataItem cnlNum="600002">Напряжение</DataItem>
      </Data>
    </Location>

  </LayerGroup>
</MapView>
